fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x0a0a10);
    if host::display::state_get(0) == 0 {
        host::mp::auto(9);
        host::display::state_set(0, 1);
        host::display::state_set(1, w / 2);
        host::display::state_set(2, h / 2);
        host::display::state_set(3, 3);
        host::display::state_set(4, 2);
    }
    if host::mp::connected() == 0 {
        host::display::draw_string(130, 230, "WAITING FOR THE", 0x8899aa, 2);
        host::display::draw_string(140, 260, "OTHER PLAYER", 0x8899aa, 2);
        host::display::present();
    } else {
        let me: i32 = host::mp::self_index();
        let mut my_y: i32 = host::display::pointer_y() - 40;
        if my_y < 0 {
            my_y = 0;
        }
        if my_y > h - 80 {
            my_y = h - 80;
        }
        host::mp::set(0, my_y);
        if me == 0 {
            let mut bx: i32 = host::display::state_get(1);
            let mut by: i32 = host::display::state_get(2);
            let mut vx: i32 = host::display::state_get(3);
            let mut vy: i32 = host::display::state_get(4);
            bx = bx + vx;
            by = by + vy;
            if by < 0 || by > h - 10 {
                vy = 0 - vy;
            }
            let ly: i32 = host::mp::get(0, 0);
            let ry: i32 = host::mp::get(1, 0);
            if bx < 24 && by + 10 > ly && by < ly + 80 {
                vx = 0 - vx;
            }
            if bx > w - 34 && by + 10 > ry && by < ry + 80 {
                vx = 0 - vx;
            }
            if bx < 0 || bx > w {
                bx = w / 2;
                by = h / 2;
            }
            host::display::state_set(1, bx);
            host::display::state_set(2, by);
            host::display::state_set(3, vx);
            host::display::state_set(4, vy);
            host::mp::set(1, bx);
            host::mp::set(2, by);
        }
        host::display::fill_rect(14, host::mp::get(0, 0), 10, 80, 0xffcc33);
        host::display::fill_rect(w - 24, host::mp::get(1, 0), 10, 80, 0x33ff88);
        host::display::fill_rect(host::mp::get(0, 1), host::mp::get(0, 2), 10, 10, 0xffffff);
        host::display::draw_string(8, 8, "P2P PONG SHELL", 0x556677, 1);
        if me == 0 {
            host::display::draw_string(8, 22, "YOU ARE HOST - LEFT", 0xffcc33, 1);
        } else {
            host::display::draw_string(8, 22, "YOU ARE JOINER - RIGHT", 0x33ff88, 1);
        }
        host::display::present();
    }
}
